def quintile(values):
    s = sorted(values)
    n = len(s)
    cuts = [s[int(n*q)] for q in (0.2,0.4,0.6,0.8)]
    def sc(v):
        for i,c in enumerate(cuts):
            if v < c: return i+1
        return 5
    return sc

import pytest

from rfm_buggy import quintile as buggy_quintile


def test_tied_values_share_score_buggy():
    freqs = [1] * 60 + [2] * 25 + [3] * 15
    sc = buggy_quintile(freqs)
    scores = {f: sc(f) for f in set(freqs)}
    assert scores[1] == scores[1]  # trivially true; real check below
    # all customers with frequency 1 must receive the SAME score
    ones = {sc(f) for f in freqs if f == 1}
    assert len(ones) == 1, f"frequency-1 customers got multiple scores: {ones}"


def test_small_n_no_indexerror_buggy():
    with pytest.raises(IndexError):
        buggy_quintile([10, 20, 30])

